static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &p){QFile f(p);require(f.open(QIODevice::ReadOnly),"Region-zoom artifact missing");return f.readAll();}
static void write(const QString &p,const QByteArray &b){QFile f(p);require(f.open(QIODevice::WriteOnly)&&f.write(b)==b.size(),"Region-zoom artifact write failed");}
static QByteArray samples(const PlotModel &m){QByteArray b;QDataStream s(&b,QIODevice::WriteOnly);for(const auto &c:m.curves)for(const auto &p:c.points)s<<p.frame<<p.epoch<<p.x<<p.y<<p.z<<p.connect<<p.solver;return b;}
static QString digest(const QByteArray &b){return QString::fromLatin1(QCryptographicHash::hash(b,QCryptographicHash::Sha256).toHex());}
static QImage logical(PlotCanvas *c){const auto p=c->captureImage();require(!p.isNull()&&p.size()==QSize(qRound(c->width()*c->devicePixelRatioF()),qRound(c->height()*c->devicePixelRatioF())),"Region-zoom capture physical/logical dimensions differ");auto image=p.scaled(c->size(),Qt::IgnoreAspectRatio,Qt::SmoothTransformation);image.setDevicePixelRatio(1);return image;}
static bool red(const QImage &im,QPoint p){for(int y=p.y()-5;y<=p.y()+5;++y)for(int x=p.x()-5;x<=p.x()+5;++x)if(im.rect().contains(x,y)){const auto c=im.pixelColor(x,y);if(c.red()>160&&c.green()<100&&c.blue()<100)return true;}return false;}
static void move(PlotCanvas *c,QPoint p,Qt::KeyboardModifiers mods=Qt::NoModifier){QMouseEvent e(QEvent::MouseMove,p,c->mapToGlobal(p),Qt::NoButton,Qt::LeftButton,mods);QApplication::sendEvent(c,&e);events();}
static void wheel(PlotCanvas *c,int delta){QPointF p=c->rect().center();QWheelEvent e(p,c->mapToGlobal(p.toPoint()),{},QPoint(0,delta),Qt::NoButton,Qt::NoModifier,Qt::NoScrollPhase,false);QApplication::sendEvent(c,&e);events();}
